public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.next();

        int[] cnt = new int[26];
        long ans = 0;

        for (char c : s.toCharArray()) {
            cnt[c - 'a'] += 1;
            ans += cnt[c - 'a'];
        }

        System.out.println(ans);
    }
}
```



